@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="someone with glasses" note=pref.avatar.accessory value="someone with glasses"

@f1 w.request.filler text=so
@r1 w.request.request act=change mood=do words="Set my avatar to a woman with glasses" predicate=Set
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="a woman with glasses" note=pref.avatar.accessory value="a woman with glasses"
@f2 w.request.filler text="so I do not have to ask again"
@r2 w.request.request act=change mood=do words="keep that choice for every new session" predicate=keep
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.keep value=look operator=eq phase=result words="keep that choice for every new session"
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="for every new session" operator=eq phase=result

@f1 w.request.filler text=now
@f2 w.request.filler text=now
@r1 w.request.request act=change mood=do words="my avatar to be a figure with glasses for every session from now on"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="a figure with glasses" note=pref.avatar.accessory value="a figure with glasses"
@f3 w.request.filler text="I want"
@f4 w.request.filler text="not only for the diagram I have open right now"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=preference.scope value="for every session from now on" operator=eq phase=result

@f1 w.request.filler text=please
@r1 w.request.request act=change mood=do predicate=make words="Could you please make my avatar the one with glasses"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="avatar the one with glasses" note=pref.avatar.accessory value="the one with glasses"
@r2 w.request.request act=save mood=do words="remember that choice for later, when I open a new tab" predicate=remember
@r2.t w.request.target request=$r2 family=preference mode=existing determiner=definite fill=description description="that choice"
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="when I open a new tab" operator=eq phase=result
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="for later" operator=eq phase=result

@r1 w.request.request act=change mood=do words="my avatar should stay a person with glasses until I tell you otherwise" predicate=stay
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="a person with glasses" note=pref.avatar.accessory value="a person with glasses"
@f1 w.request.filler text="Whatever else changes on the page"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=preference.scope value="until I tell you otherwise" operator=eq phase=result
